name=[9]
class Getter:
 @property
 def __name__(self): return name
p=property(Getter())
print(p.__name__ is name)

class Getter:
 @property
 def __name__(self):
  print("name")
  return "dynamic"
p=property(Getter())
print("made")
print(p.__name__)

class Getter:
 @property
 def __name__(self):
  print("entered")
  raise ValueError("original")
p=property(Getter())
print(p.__name__)

class Getter:
 @property
 def __name__(self):
  print("entered")
  raise AttributeError("original")
p=property(Getter())
print(p.__name__)

class Getter:
 @property
 def __name__(self):
  print("never")
  raise ValueError("original")
p=property(Getter())
p.__name__=None
print(p.__name__)

